/*
 * ELF version script for the plugin module.
 *
 * libobs only ever os_dlsym()s obs_module_* out of a plugin, so nothing else
 * needs to be visible. Hiding the rest is what keeps the bundled static FFmpeg
 * from being interposed by (or interposing on) the host OBS's own FFmpeg,
 * which shares every symbol name with ours.
 */
{
	global:
		obs_module_*;
	local:
		*;
};
